create schema if not exists vistiq_recovery_20261105;
revoke all on schema vistiq_recovery_20261105 from public,anon,authenticated;
create table if not exists vistiq_recovery_20261105.verified_media (
name text primary key,
source_url text unique not null,
destination_url text not null,
bytes bigint not null
);
revoke all on vistiq_recovery_20261105.verified_media from public,anon,authenticated;
on conflict (name) do nothing;

create or replace function vistiq_recovery_20261105.normalize_verified_invitation_media()
returns trigger language plpgsql security definer set search_path = '' as $normalize$
declare document text; mapping record;
begin
document := pg_catalog.to_jsonb(new)::text;
if pg_catalog.strpos(document,'https://tvjifuzhakaymzottdyf.supabase.co/storage/v1/object/public/') = 0 then return new; end if;
for mapping in select source_url,destination_url from vistiq_recovery_20261105.verified_media loop
document := pg_catalog.replace(document,mapping.source_url,mapping.destination_url);
end loop;
new := pg_catalog.jsonb_populate_record(new,document::jsonb);
return new;
end;
$normalize$;
revoke all on function vistiq_recovery_20261105.normalize_verified_invitation_media() from public,anon,authenticated;
create trigger normalize_verified_invitation_media before insert or update on public.invitations
for each row execute function vistiq_recovery_20261105.normalize_verified_invitation_media();

create policy owner_delete_verified_recovery_media on storage.objects
for delete to authenticated
